def Hello_Tool(**_extra):
    import json, os, datetime, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0260000" if __import__("os").path.isdir("./environment_mix/0260000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _isoz(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _audit(tool_name, request_params, normalized_file_path, status, started_at=None, finished_at=None, duration_ms=None, response_payload=None, error_code=None, error_message=None):
        invs = _load("tool_invocations.json")
        if not isinstance(invs, list):
            invs = []
        existing = {r.get("id") for r in invs if isinstance(r, dict)}
        inv_id = _gen_id("mcp_inv_")
        while inv_id in existing:
            inv_id = _gen_id("mcp_inv_")
        now = _utcnow()
        row = {
            "id": inv_id,
            "tool_name": tool_name,
            "request_params": request_params,
            "normalized_file_path": normalized_file_path,
            "status": status,
            "response_payload": response_payload,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "duration_ms": duration_ms,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        invs.append(row)
        _save("tool_invocations.json", invs)
        return row

    # Quota enforcement: datastore has no explicit quotas/rate limits; do not fabricate limits.
    # Execute and record as a full lifecycle: received -> running -> succeeded.
    t_start = time.time()
    started = _utcnow()

    inv = _audit(
        tool_name="Hello Tool",
        request_params={},
        normalized_file_path=None,
        status="running",
        started_at=_isoz(started),
        finished_at=None,
        duration_ms=None,
        response_payload=None,
        error_code=None,
        error_message=None,
    )

    # Succeed
    msg = "Hello from the MCP agent. Tools are available: Hello, Users, Textract."
    finished = _utcnow()
    duration_ms = int(round((time.time() - t_start) * 1000))
    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        return _err("CONFLICT", "Invocation log is not readable")
    for i, r in enumerate(invs):
        if isinstance(r, dict) and r.get("id") == inv["id"]:
            r["status"] = "succeeded"
            r["response_payload"] = msg
            r["error_code"] = None
            r["error_message"] = None
            r["finished_at"] = _isoz(finished)
            r["duration_ms"] = duration_ms
            r["updated_at"] = _isoz(_utcnow())
            invs[i] = r
            _save("tool_invocations.json", invs)
            return {"tool_invocation": r, "hello": msg}
    return _err("NOT_FOUND", "Invocation disappeared during update")

def Users_Tool(useCache=None, cacheTtlSeconds=None, provider=None, requestUrl=None, limit=None, cursor=None, sort=None, order=None, refresh=None, invocationId=None, **_extra):
    import json, os, datetime, secrets, time, hashlib, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0260000" if __import__("os").path.isdir("./environment_mix/0260000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _isoz(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _stable_cache_key(p, url):
        return hashlib.sha256((p + "|" + url).encode("utf-8")).hexdigest()

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str):
            return None
        if not c.startswith("o:"):
            return None
        try:
            n = int(c[2:])
            if n < 0:
                return None
            return n
        except Exception:
            return None

    def _encode_cursor(offset):
        return "o:" + str(offset)

    # Defaults & validation
    if useCache is None:
        useCache = True
    if refresh is None:
        refresh = False
    if cacheTtlSeconds is None:
        cacheTtlSeconds = 300
    if provider is None:
        provider = "jsonplaceholder"
    if limit is None:
        limit = 50
    if order is None:
        order = "asc"

    if not isinstance(useCache, bool):
        return _err("VALIDATION_ERROR", "useCache must be a boolean")
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")
    if not isinstance(cacheTtlSeconds, int):
        return _err("VALIDATION_ERROR", "cacheTtlSeconds must be an integer")
    if cacheTtlSeconds < 0 or cacheTtlSeconds > 86400:
        return _err("VALIDATION_ERROR", "cacheTtlSeconds must be between 0 and 86400")
    if provider not in ("jsonplaceholder", "unknown"):
        return _err("VALIDATION_ERROR", "provider is not a valid enum value")
    if requestUrl is not None and not isinstance(requestUrl, str):
        return _err("VALIDATION_ERROR", "requestUrl must be a string")
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is not None and sort not in ("id", "name", "username", "email"):
        return _err("VALIDATION_ERROR", "sort is not a valid enum value")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order is not a valid enum value")
    if invocationId is not None and not isinstance(invocationId, str):
        return _err("VALIDATION_ERROR", "invocationId must be a string")

    default_url = "https://jsonplaceholder.typicode.com/users" if provider == "jsonplaceholder" else "https://example.invalid/users"
    url = requestUrl if requestUrl else default_url

    # Create or reuse invocation
    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        invs = []

    now = _utcnow()
    inv_row = None
    if invocationId:
        inv_row = next((r for r in invs if isinstance(r, dict) and r.get("id") == invocationId), None)
        if inv_row is None:
            return _err("NOT_FOUND", "invocationId not found")
        if inv_row.get("tool_name") != "Users Tool":
            return _err("CONFLICT", "invocationId exists but is not a Users Tool invocation")
        if inv_row.get("request_params") != {}:
            return _err("CONFLICT", "Users Tool invocation request_params must be {}")
        if inv_row.get("status") in ("succeeded", "failed"):
            return _err("INVALID_TRANSITION", "Invocation is terminal and cannot be re-run")
        inv_id = invocationId
    else:
        existing = {r.get("id") for r in invs if isinstance(r, dict)}
        inv_id = _gen_id("mcp_inv_")
        while inv_id in existing:
            inv_id = _gen_id("mcp_inv_")
        inv_row = {
            "id": inv_id,
            "tool_name": "Users Tool",
            "request_params": {},
            "normalized_file_path": None,
            "status": "received",
            "response_payload": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        invs.append(inv_row)
        _save("tool_invocations.json", invs)

    # Transition invocation received -> running (or keep running)
    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        return _err("CONFLICT", "Invocation log is not readable")
    for i, r in enumerate(invs):
        if isinstance(r, dict) and r.get("id") == inv_id:
            if r.get("status") == "received":
                r["status"] = "running"
                r["started_at"] = r.get("started_at") or _isoz(_utcnow())
                r["updated_at"] = _isoz(_utcnow())
                invs[i] = r
                _save("tool_invocations.json", invs)
            elif r.get("status") == "running":
                if not r.get("started_at"):
                    r["started_at"] = _isoz(_utcnow())
                    r["updated_at"] = _isoz(_utcnow())
                    invs[i] = r
                    _save("tool_invocations.json", invs)
            elif r.get("status") in ("succeeded", "failed"):
                return _err("INVALID_TRANSITION", "Invocation is terminal and cannot be advanced")
            inv_row = r
            break
    else:
        return _err("NOT_FOUND", "Tool invocation not found")

    started_dt = _parse_dt(inv_row.get("started_at")) or _utcnow()
    t0 = time.time()

    # Must create exactly one external_user_fetches row per invocation_id
    fetches = _load("external_user_fetches.json")
    if not isinstance(fetches, list):
        fetches = []
    existing_fetch = next((f for f in fetches if isinstance(f, dict) and f.get("invocation_id") == inv_id), None)
    if existing_fetch is not None:
        return _err("CONFLICT", "An external_user_fetches row already exists for this invocation_id")

    # Cache lookup (can use any previous fetch with same cache_key and not expired)
    cache_key = _stable_cache_key(provider, url)
    cached_body = None
    cached_row = None
    if useCache and (not refresh):
        for f in fetches:
            if not isinstance(f, dict):
                continue
            if f.get("cache_key") != cache_key:
                continue
            if f.get("status") != "succeeded":
                continue
            exp = _parse_dt(f.get("cache_expires_at"))
            if exp is None:
                continue
            if exp > _utcnow() and isinstance(f.get("response_body"), list):
                cached_body = f.get("response_body")
                cached_row = f
                break

    # Create attempted fetch row
    existing_ids = {r.get("id") for r in fetches if isinstance(r, dict)}
    fetch_id = _gen_id("mcp_usrfetch_")
    while fetch_id in existing_ids:
        fetch_id = _gen_id("mcp_usrfetch_")
    created = _utcnow()
    ttl = cacheTtlSeconds
    expires = created + datetime.timedelta(seconds=ttl)
    fetch_row = {
        "id": fetch_id,
        "invocation_id": inv_id,
        "provider": provider,
        "request_url": url,
        "http_status": None,
        "response_body": None,
        "etag": None,
        "fetched_at": None,
        "cache_key": cache_key,
        "cache_ttl_seconds": ttl,
        "cache_expires_at": _isoz(expires),
        "status": "attempted",
        "error_message": None,
        "created_at": _isoz(created),
        "updated_at": _isoz(created),
    }
    fetches.append(fetch_row)
    _save("external_user_fetches.json", fetches)

    # If cached, mark fetch as succeeded without calling upstream (still records invocation-triggered "fetch")
    users = None
    http_status = None
    etag = None
    fetched_at = _utcnow()
    if cached_body is not None:
        users = cached_body
        http_status = 200
        etag = cached_row.get("etag")
        fetch_row["status"] = "succeeded"
        fetch_row["http_status"] = http_status
        fetch_row["response_body"] = users
        fetch_row["etag"] = etag
        fetch_row["fetched_at"] = _isoz(fetched_at)
        fetch_row["updated_at"] = _isoz(_utcnow())
        fetch_row["error_message"] = None
        # persist update
        fetches = _load("external_user_fetches.json")
        for i, r in enumerate(fetches):
            if isinstance(r, dict) and r.get("id") == fetch_id:
                fetches[i] = fetch_row
                _save("external_user_fetches.json", fetches)
                break
    else:
        # Perform external request (best-effort; offline errors become EXTERNAL_API_ERROR)
        try:
            req = urllib.request.Request(url, method="GET", headers={"User-Agent": "mcp-server/1.0"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                http_status = int(getattr(resp, "status", 200))
                body_bytes = resp.read()
                etag = resp.headers.get("ETag")
            try:
                users = json.loads(body_bytes.decode("utf-8"))
            except Exception:
                users = None
                raise ValueError("Invalid JSON response from provider")
            if not isinstance(users, list):
                raise ValueError("Provider response was not a JSON array")
            fetch_row["status"] = "succeeded"
            fetch_row["http_status"] = http_status
            fetch_row["response_body"] = users
            fetch_row["etag"] = etag
            fetch_row["fetched_at"] = _isoz(fetched_at)
            fetch_row["updated_at"] = _isoz(_utcnow())
            fetch_row["error_message"] = None
        except urllib.error.HTTPError as e:
            fetch_row["status"] = "failed"
            fetch_row["http_status"] = int(getattr(e, "code", 0) or 0) or None
            fetch_row["response_body"] = None
            fetch_row["etag"] = None
            fetch_row["fetched_at"] = _isoz(fetched_at)
            fetch_row["updated_at"] = _isoz(_utcnow())
            fetch_row["error_message"] = f"Upstream HTTPError: {getattr(e, 'code', None)}"
            users = None
        except (urllib.error.URLError, ValueError, TimeoutError) as e:
            fetch_row["status"] = "failed"
            fetch_row["http_status"] = None
            fetch_row["response_body"] = None
            fetch_row["etag"] = None
            fetch_row["fetched_at"] = _isoz(fetched_at)
            fetch_row["updated_at"] = _isoz(_utcnow())
            fetch_row["error_message"] = str(e) or "Upstream request failed"
            users = None

        # persist fetch row final state
        fetches = _load("external_user_fetches.json")
        if not isinstance(fetches, list):
            return _err("CONFLICT", "Fetch log is not readable")
        for i, r in enumerate(fetches):
            if isinstance(r, dict) and r.get("id") == fetch_id:
                fetches[i] = fetch_row
                _save("external_user_fetches.json", fetches)
                break

    # If fetch failed, invocation fails
    if users is None:
        finished = _utcnow()
        duration_ms = int(round((time.time() - t0) * 1000))
        invs = _load("tool_invocations.json")
        for i, r in enumerate(invs):
            if isinstance(r, dict) and r.get("id") == inv_id:
                if r.get("status") not in ("running", "received"):
                    return _err("INVALID_TRANSITION", "Invocation is not in a mutable state")
                r["status"] = "failed"
                r["response_payload"] = None
                r["error_code"] = "EXTERNAL_API_ERROR"
                r["error_message"] = fetch_row.get("error_message") or "External provider fetch failed"
                r["finished_at"] = _isoz(finished)
                r["duration_ms"] = duration_ms
                r["updated_at"] = _isoz(_utcnow())
                invs[i] = r
                _save("tool_invocations.json", invs)
                return {"tool_invocation": r, "external_user_fetch": fetch_row}
        return _err("NOT_FOUND", "Tool invocation not found")

    # Sort/paginate
    if sort is not None:
        def _key(u):
            v = u.get(sort) if isinstance(u, dict) else None
            return (v is None, v)
        users_sorted = sorted(users, key=_key, reverse=(order == "desc"))
    else:
        users_sorted = list(users)

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")
    total = len(users_sorted)
    page = users_sorted[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    # Invocation succeeds
    response_payload = {
        "users": page,
        "page": {"limit": limit, "cursor": cursor, "nextCursor": next_cursor, "hasMore": has_more, "total": total},
        "source": "cache" if cached_body is not None else "live",
        "provider": provider,
        "requestUrl": url,
    }
    finished = _utcnow()
    duration_ms = int(round((time.time() - t0) * 1000))
    invs = _load("tool_invocations.json")
    for i, r in enumerate(invs):
        if isinstance(r, dict) and r.get("id") == inv_id:
            if r.get("status") not in ("running", "received"):
                return _err("INVALID_TRANSITION", "Invocation is not in a mutable state")
            r["status"] = "succeeded"
            r["response_payload"] = response_payload
            r["error_code"] = None
            r["error_message"] = None
            r["finished_at"] = _isoz(finished)
            r["duration_ms"] = duration_ms
            if not r.get("started_at"):
                r["started_at"] = _isoz(started_dt)
            r["updated_at"] = _isoz(_utcnow())
            invs[i] = r
            _save("tool_invocations.json", invs)
            return {
                "tool_invocation": r,
                "external_user_fetch": fetch_row,
                "users": page,
                "page": {"limit": limit, "nextCursor": next_cursor, "hasMore": has_more, "total": total},
            }
    return _err("NOT_FOUND", "Tool invocation not found")

def Textract_Tool(filePath, **_extra):
    import json, os, datetime, secrets, time, hashlib, mimetypes
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0260000" if __import__("os").path.isdir("./environment_mix/0260000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _isoz(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    # Validate input (per tool schema)
    if not isinstance(filePath, str):
        return _err("VALIDATION_ERROR", "filePath must be a string")
    if not filePath.strip():
        return _err("VALIDATION_ERROR", "filePath is required and must be non-empty")

    try:
        normalized_path = os.path.abspath(os.path.expanduser(filePath))
    except Exception:
        return _err("VALIDATION_ERROR", "filePath could not be normalized")

    ext = os.path.splitext(normalized_path)[1].lower().lstrip(".")
    supported = {"pdf", "png", "jpg", "jpeg", "tiff", "tif"}
    if ext not in supported:
        return _err("VALIDATION_ERROR", "Unsupported file type", supportedExtensions=sorted(supported))

    # Create invocation row in received
    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        invs = []
    existing = {r.get("id") for r in invs if isinstance(r, dict)}
    inv_id = _gen_id("mcp_inv_")
    while inv_id in existing:
        inv_id = _gen_id("mcp_inv_")
    now = _utcnow()
    inv_row = {
        "id": inv_id,
        "tool_name": "Textract Tool",
        "request_params": {"filePath": filePath},
        "normalized_file_path": normalized_path,
        "status": "received",
        "response_payload": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": _isoz(now),
        "updated_at": _isoz(now),
    }
    invs.append(inv_row)
    _save("tool_invocations.json", invs)

    # Transition invocation -> running
    invs = _load("tool_invocations.json")
    for i, r in enumerate(invs):
        if isinstance(r, dict) and r.get("id") == inv_id:
            r["status"] = "running"
            r["started_at"] = _isoz(_utcnow())
            r["updated_at"] = _isoz(_utcnow())
            invs[i] = r
            _save("tool_invocations.json", invs)
            inv_row = r
            break

    t0 = time.time()

    # Must create exactly one textract_jobs row linked by invocation_id
    jobs = _load("textract_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    if any(isinstance(j, dict) and j.get("invocation_id") == inv_id for j in jobs):
        return _err("CONFLICT", "A textract_jobs row already exists for this invocation_id")

    job_id = _gen_id("mcp_txj_")
    existing_job_ids = {r.get("id") for r in jobs if isinstance(r, dict)}
    while job_id in existing_job_ids:
        job_id = _gen_id("mcp_txj_")

    job_created = _utcnow()
    job_row = {
        "id": job_id,
        "invocation_id": inv_id,
        "file_path": filePath,
        "file_sha256": None,
        "content_type": None,
        "file_size_bytes": None,
        "textract_mode": "analyze_document" if ext == "pdf" else "detect_document_text",
        "aws_region": None,
        "aws_request_id": None,
        "status": "queued",
        "submitted_at": None,
        "completed_at": None,
        "error_message": None,
        "created_at": _isoz(job_created),
        "updated_at": _isoz(job_created),
    }
    jobs.append(job_row)
    _save("textract_jobs.json", jobs)

    # Try to read file; must fail with error_code FILE_NOT_FOUND if cannot be read
    try:
        with open(normalized_path, "rb") as f:
            data = f.read()
    except OSError:
        # Mark job failed (queued -> failed is allowed)
        jobs = _load("textract_jobs.json")
        for i, j in enumerate(jobs):
            if isinstance(j, dict) and j.get("id") == job_id:
                j["status"] = "failed"
                j["error_message"] = f"FILE_NOT_FOUND: cannot open {normalized_path}"
                j["completed_at"] = _isoz(_utcnow())
                j["updated_at"] = _isoz(_utcnow())
                jobs[i] = j
                _save("textract_jobs.json", jobs)
                job_row = j
                break
        # Mark invocation failed
        invs = _load("tool_invocations.json")
        for i, r in enumerate(invs):
            if isinstance(r, dict) and r.get("id") == inv_id:
                finished = _utcnow()
                duration_ms = int(round((time.time() - t0) * 1000))
                r["status"] = "failed"
                r["response_payload"] = None
                r["error_code"] = "FILE_NOT_FOUND"
                r["error_message"] = f"FILE_NOT_FOUND: cannot open {normalized_path}"
                r["finished_at"] = _isoz(finished)
                r["duration_ms"] = duration_ms
                r["updated_at"] = _isoz(_utcnow())
                invs[i] = r
                _save("tool_invocations.json", invs)
                return {"tool_invocation": r, "textract_job": job_row}
        return _err("NOT_FOUND", "Tool invocation not found")

    # Update job metadata (queued -> uploading -> processing -> succeeded)
    size = len(data)
    sha = hashlib.sha256(data).hexdigest()
    ctype = mimetypes.guess_type(normalized_path)[0]
    if ctype is None:
        ctype = "application/pdf" if ext == "pdf" else ("image/" + ("jpeg" if ext in ("jpg", "jpeg") else ("tiff" if ext in ("tif", "tiff") else "png")))

    jobs = _load("textract_jobs.json")
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            if j.get("status") != "queued":
                return _err("INVALID_TRANSITION", "Textract job is not in queued state")
            j["status"] = "uploading"
            j["file_size_bytes"] = size
            j["file_sha256"] = sha
            j["content_type"] = ctype
            j["updated_at"] = _isoz(_utcnow())
            jobs[i] = j
            _save("textract_jobs.json", jobs)
            job_row = j
            break

    jobs = _load("textract_jobs.json")
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            if j.get("status") != "uploading":
                return _err("INVALID_TRANSITION", "Textract job is not in uploading state")
            j["status"] = "processing"
            j["submitted_at"] = _isoz(_utcnow())
            j["updated_at"] = _isoz(_utcnow())
            jobs[i] = j
            _save("textract_jobs.json", jobs)
            job_row = j
            break

    # Offline "Textract": extract best-effort text for plain demonstration
    extracted_text = None
    confidence_avg = None
    if ext == "pdf":
        extracted_text = None  # no PDF parsing in stdlib
    else:
        # Not real OCR; store placeholder indicating the file was accepted and hashed.
        extracted_text = None

    raw_response = {
        "mode": job_row.get("textract_mode"),
        "note": "Offline backend: no AWS call performed; job marked succeeded after local file read.",
        "file_sha256": sha,
        "file_size_bytes": size,
        "content_type": ctype,
    }

    # Succeed the job
    jobs = _load("textract_jobs.json")
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            if j.get("status") != "processing":
                return _err("INVALID_TRANSITION", "Textract job is not in processing state")
            j["status"] = "succeeded"
            j["completed_at"] = _isoz(_utcnow())
            j["error_message"] = None
            j["updated_at"] = _isoz(_utcnow())
            jobs[i] = j
            _save("textract_jobs.json", jobs)
            job_row = j
            break

    # Create results row only when job succeeded
    results = _load("textract_results.json")
    if not isinstance(results, list):
        results = []
    # next version (monotonic); schema digest says v1 exists, but allow if missing
    existing_versions = [r.get("result_version") for r in results if isinstance(r, dict) and r.get("textract_job_id") == job_id]
    next_ver = 1
    try:
        if existing_versions:
            next_ver = max(int(v) for v in existing_versions if isinstance(v, int) or (isinstance(v, str) and str(v).isdigit())) + 1
    except Exception:
        next_ver = 1
    if any(isinstance(r, dict) and r.get("textract_job_id") == job_id and r.get("result_version") == next_ver for r in results):
        return _err("CONFLICT", "Result version already exists for this job")

    txr_id = _gen_id("mcp_txr_")
    existing_txr_ids = {r.get("id") for r in results if isinstance(r, dict)}
    while txr_id in existing_txr_ids:
        txr_id = _gen_id("mcp_txr_")
    r_now = _utcnow()
    result_row = {
        "id": txr_id,
        "textract_job_id": job_id,
        "result_version": next_ver,
        "raw_response": raw_response,
        "extracted_text": extracted_text,
        "blocks": None,
        "confidence_avg": confidence_avg,
        "created_at": _isoz(r_now),
        "updated_at": _isoz(r_now),
    }
    results.append(result_row)
    _save("textract_results.json", results)

    # Mark invocation succeeded
    invs = _load("tool_invocations.json")
    for i, r in enumerate(invs):
        if isinstance(r, dict) and r.get("id") == inv_id:
            finished = _utcnow()
            duration_ms = int(round((time.time() - t0) * 1000))
            payload = {
                "textract_job_id": job_id,
                "status": job_row.get("status"),
                "result_version": result_row.get("result_version"),
                "content_type": ctype,
                "file_size_bytes": size,
                "file_sha256": sha,
            }
            r["status"] = "succeeded"
            r["response_payload"] = payload
            r["error_code"] = None
            r["error_message"] = None
            r["finished_at"] = _isoz(finished)
            r["duration_ms"] = duration_ms
            r["updated_at"] = _isoz(_utcnow())
            invs[i] = r
            _save("tool_invocations.json", invs)
            return {"tool_invocation": r, "textract_job": job_row, "textract_result": result_row}
    return _err("NOT_FOUND", "Tool invocation not found")

def List_Tool_Invocations(cursor=None, limit=None, toolName=None, status=None, createdAfter=None, createdBefore=None, invocationId=None, includeResponsePayload=None, includeErrorDetails=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0260000" if __import__("os").path.isdir("./environment_mix/0260000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string")
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string")

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str):
            return None
        if not c.startswith("o:"):
            return None
        try:
            n = int(c[2:])
            return n if n >= 0 else None
        except Exception:
            return None

    def _encode_cursor(n):
        return "o:" + str(n)

    if limit is None:
        limit = 50
    if includeResponsePayload is None:
        includeResponsePayload = False
    if includeErrorDetails is None:
        includeErrorDetails = True

    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if toolName is not None and toolName not in ("Hello Tool", "Users Tool", "Textract Tool"):
        return _err("VALIDATION_ERROR", "toolName is not a valid enum value")
    if status is not None and status not in ("received", "running", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "status is not a valid enum value")
    if not isinstance(includeResponsePayload, bool):
        return _err("VALIDATION_ERROR", "includeResponsePayload must be a boolean")
    if not isinstance(includeErrorDetails, bool):
        return _err("VALIDATION_ERROR", "includeErrorDetails must be a boolean")
    if invocationId is not None and not isinstance(invocationId, str):
        return _err("VALIDATION_ERROR", "invocationId must be a string")

    dt_after, e = _parse_dt(createdAfter, "createdAfter")
    if e: return e
    dt_before, e = _parse_dt(createdBefore, "createdBefore")
    if e: return e

    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        invs = []

    # Filter
    rows = []
    for r in invs:
        if not isinstance(r, dict):
            continue
        if invocationId is not None and r.get("id") != invocationId:
            continue
        if toolName is not None and r.get("tool_name") != toolName:
            continue
        if status is not None and r.get("status") != status:
            continue
        created_dt, _ = _parse_dt(r.get("created_at"), "created_at")
        if dt_after is not None and (created_dt is None or created_dt < dt_after):
            continue
        if dt_before is not None and (created_dt is None or created_dt >= dt_before):
            continue
        rows.append(r)

    # Sort by created_at desc (most recent first), stable fallback to id
    def _sort_key(r):
        d, _ = _parse_dt(r.get("created_at"), "created_at")
        return (d is None, d if d is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    # Shape response items
    items = []
    for r in page:
        item = dict(r)
        if not includeResponsePayload:
            item.pop("response_payload", None)
        if not includeErrorDetails:
            item.pop("error_code", None)
            item.pop("error_message", None)
        items.append(item)

    return {"invocations": items, "page": {"limit": limit, "nextCursor": next_cursor, "hasMore": has_more, "total": total}}

