def Update_Tool_Invocation_Status(id, status, startedAt=None, finishedAt=None, durationMs=None, responsePayload=None, errorCode=None, errorMessage=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0260000" if __import__("os").path.isdir("./environment_mix/0260000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    transitions = {
        "received": ["running", "failed"],
        "running": ["succeeded", "failed"],
        "succeeded": [],
        "failed": [],
    }

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _isoz(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Validate; be permissive with id passed incorrectly by callers in audit: if int, treat as NOT_FOUND not schema error
    if not isinstance(id, str):
        return _err("VALIDATION_ERROR", "id must be a string")
    if not re.match(r"^mcp_inv_[0-9A-HJKMNP-TV-Z]{26}$", id):
        return _err("VALIDATION_ERROR", "id does not match required pattern")

    if not isinstance(status, str) or status not in ("received", "running", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "status is not a valid enum value")

    dt_started, e = _parse_dt(startedAt, "startedAt")
    if e: return e
    dt_finished, e = _parse_dt(finishedAt, "finishedAt")
    if e: return e

    if durationMs is not None and (not isinstance(durationMs, int) or durationMs < 0):
        return _err("VALIDATION_ERROR", "durationMs must be a non-negative integer")

    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        invs = []
    idx = next((i for i, r in enumerate(invs) if isinstance(r, dict) and r.get("id") == id), None)
    if idx is None:
        return _err("NOT_FOUND", "Tool invocation not found")
    row = invs[idx]
    cur = row.get("status")
    if cur not in transitions:
        return _err("CONFLICT", "Stored invocation status is invalid")

    # Enforce forward transitions unless idempotent same-state update of timestamps/updated_at
    if status != cur:
        if status not in transitions.get(cur, []):
            return _err("INVALID_TRANSITION", f"Cannot transition tool invocation from {cur} to {status}")
    else:
        # idempotent update allowed (e.g., setting startedAt when already running)
        pass

    # Business rules on terminal states
    if status == "succeeded":
        if responsePayload is None:
            return _err("VALIDATION_ERROR", "responsePayload must be provided when status becomes succeeded")
        if errorCode is not None or errorMessage is not None:
            return _err("VALIDATION_ERROR", "errorCode/errorMessage must be null when status becomes succeeded")
        if dt_finished is None and row.get("finished_at") is None:
            return _err("VALIDATION_ERROR", "finishedAt is required when status becomes succeeded")
    if status == "failed":
        if not isinstance(errorMessage, str) or not errorMessage.strip():
            return _err("VALIDATION_ERROR", "errorMessage must be provided when status becomes failed")
        if responsePayload is not None:
            return _err("VALIDATION_ERROR", "responsePayload must be null when status becomes failed")
        if dt_finished is None and row.get("finished_at") is None:
            return _err("VALIDATION_ERROR", "finishedAt is required when status becomes failed")

    # startedAt required when moving to running if not already set
    if status == "running" and row.get("started_at") is None and dt_started is None:
        return _err("VALIDATION_ERROR", "startedAt is required when moving to running if not already set")

    # Apply updates
    now = datetime.datetime.now(datetime.timezone.utc)
    if status != cur:
        row["status"] = status

    if status == "running":
        if row.get("started_at") is None:
            row["started_at"] = _isoz(dt_started)
        elif dt_started is not None:
            # allow setting started_at if it was missing; if present, keep original
            pass

    if status in ("succeeded", "failed"):
        if row.get("started_at") is None and dt_started is not None:
            row["started_at"] = _isoz(dt_started)
        if dt_finished is not None:
            row["finished_at"] = _isoz(dt_finished)
        # duration_ms must match finished-started within tolerance when terminal if provided
        started_dt, _ = _parse_dt(row.get("started_at"), "started_at")
        finished_dt, _ = _parse_dt(row.get("finished_at"), "finished_at")
        if started_dt is None or finished_dt is None:
            return _err("VALIDATION_ERROR", "startedAt and finishedAt must be set on terminal states")
        if finished_dt < started_dt:
            return _err("VALIDATION_ERROR", "finishedAt must be >= startedAt")
        computed = int(round((finished_dt - started_dt).total_seconds() * 1000))
        if durationMs is not None:
            if abs(computed - durationMs) > 50:
                return _err("VALIDATION_ERROR", "durationMs must match (finishedAt-startedAt) within tolerance", computedMs=computed)
            row["duration_ms"] = durationMs
        else:
            row["duration_ms"] = computed

        if status == "succeeded":
            row["response_payload"] = responsePayload
            row["error_code"] = None
            row["error_message"] = None
        else:
            row["response_payload"] = None
            row["error_code"] = errorCode
            row["error_message"] = errorMessage

    row["updated_at"] = _isoz(now)
    invs[idx] = row
    _save("tool_invocations.json", invs)
    return {"tool_invocation": row}

