            return _err("VALIDATION_ERROR", "completedAt is required when entering succeeded or failed")
        if status == "failed":
            if not isinstance(errorMessage, str) or not errorMessage.strip():
                return _err("VALIDATION_ERROR", "errorMessage is required when setting status to failed")
        if status == "succeeded":
            if errorMessage is not None:
                return _err("VALIDATION_ERROR", "errorMessage must be null when setting status to succeeded")

    # Apply
    now = datetime.datetime.now(datetime.timezone.utc)
    if status != cur:
        row["status"] = status
    if awsRequestId is not None:
        row["aws_request_id"] = awsRequestId
    if status == "processing":
        if row.get("submitted_at") is None:
            row["submitted_at"] = _isoz(dt_sub)
    if dt_sub is not None and row.get("submitted_at") is None:
        row["submitted_at"] = _isoz(dt_sub)
    if status in ("succeeded", "failed"):
        if dt_comp is not None:
            row["completed_at"] = _isoz(dt_comp)
        if status == "failed":
            row["error_message"] = errorMessage
        else:
            row["error_message"] = None

    # Validate time ordering if both set
    if row.get("completed_at") is not None:
        sub, _ = _parse_dt(row.get("submitted_at"), "submitted_at")
        comp, _ = _parse_dt(row.get("completed_at"), "completed_at")
        if comp is None:
            return _err("VALIDATION_ERROR", "completedAt is invalid")
        if sub is None:
            return _err("VALIDATION_ERROR", "submittedAt must be set before completedAt")
        if comp < sub:
            return _err("VALIDATION_ERROR", "completedAt must be >= submittedAt")

    row["updated_at"] = _isoz(now)
    jobs[idx] = row
    _save("textract_jobs.json", jobs)
    return {"textract_job": row}
